  const charImgUrl = character ? (character.imageUrl || null) : null;

  const charRef = charBible ? '\nCharacter reference (maintain visual consistency): ' + charBible : '';
  const textPart = {
    text: 'Generate a cinematic ' + ($json.scene.aspect_ratio || '16:9') + ' image.' +
          '\nStyle: ' + $json.style_bible + charRef +
          '\nScene ' + $json.scene.scene_id + ': ' + $json.scene.image_prompt +
          '\nNo text overlays, no watermarks, no logos.'
  };

  const parts = [textPart];
  if (charImgUrl) {
    parts.push({ fileData: { mimeType: 'image/jpeg', fileUri: charImgUrl } });
  }

  return JSON.stringify({
    contents: [{ parts }],
    generationConfig: { responseModalities: ['TEXT', 'IMAGE'] }
  });
})() }}

