parameters.jsCode:
const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData?.data);
const b64 = imgPart?.inlineData?.data || null;
const mime = imgPart?.inlineData?.mimeType || 'image/png';
const url = b64 ? `data:${mime};base64,${b64}` : null;
const manifest = $('Code - Build Manifest').first().json;
return [{ json: { ...manifest, thumbnail_url: url } }];

const config = $input.first().json;
const prov = config.providers.script;

const prompt = `You are a professional video scriptwriter. Write a natural, engaging voice-over script for a ${config.channel_niche || 'general'} channel in ${config.language || 'English'}.

The script must:
- Be suitable for voice-over narration only (no stage directions, no scene descriptions)
- Target duration: ${config.target_duration_sec || 60} seconds when read aloud at normal pace (~130 words/min)
- Match the visual style: ${config.visual_style || 'cinematic'}
- Cover all key points from the narration content below

Title: ${config.title}

Narration content:
${config.narration_script}

Output ONLY the voice-over script text. No headers, no explanations, no markdown.`;

let voice_request;
if (prov.requestFormat === 'claude_messages') {
  voice_request = {
    url: prov.url,
    headers: {
      'x-api-key': prov.authValue,
      'anthropic-version': ((prov.extraHeaders || {})['anthropic-version'] || '2023-06-01'),
      'content-type': 'application/json',
    },
    body: { model: prov.model, max_tokens: 2048, messages: [{ role: 'user', content: prompt }] },
  };
} else {
  // openai_chat — Gemini compat
  voice_request = {
    url: prov.url,
    headers: { [prov.authName]: prov.authValue, 'content-type': 'application/json' },
    body: { model: prov.model, messages: [{ role: 'user', content: prompt }] },
  };
}

return [{ json: { ...config, voice_request } }];

const resp = $input.first().json;
const config = $('Code - Build Voice Request').first().json;

let voice_script = '';
if (resp.content?.[0]?.text) {
  voice_script = resp.content[0].text.trim();
} else if (resp.choices?.[0]?.message?.content) {
  voice_script = resp.choices[0].message.content.trim();
}

if (!voice_script) throw new Error('Voice Script Resolver: LLM returned empty response');

// Rebuild script_request user message with the resolved voice_script
const sr = config.script_request;
const sceneCountLabel = config.scene_count || 'an appropriate number of';
const durationLabel = config.target_duration_sec || (config.scene_seconds * (config.scene_count || 8));
const newUserContent = `Divide the voice-over script below into EXACTLY ${sceneCountLabel} scenes. Target duration: ${durationLabel}s (~${config.scene_seconds}s per scene). Aspect ratio: ${config.aspect_ratio}.

Voice-over script (divide this verbatim into scenes):
"""
${voice_script}
"""

Title: ${config.title}

JSON output format:
{
  "style_bible": "global visual rules: palette, lens style, lighting, mood used across ALL scenes",
  "character_bible": "consistent physical appearance and visual traits of the character across all scenes (empty string if no character)",
  "scenes": [
    {
      "scene_id": 1,
      "start_sec": 0,
      "end_sec": ${config.scene_seconds},
      "narration_text": "<verbatim copy-paste from the script above>",
      "image_prompt": "...",
      "video_prompt": "...",
      "camera_motion": "dolly_in",
      "sound_design": "...",
      "has_character": true
    }
  ]
}

IMPORTANT: Before outputting, verify scenes.length === ${sceneCountLabel}. Verify narration_text values are verbatim from the script.`;
const updatedMessages = sr.body.messages.map(m => m.role === 'user' ? { ...m, content: newUserContent } : m);
const script_request = { ...sr, body: { ...sr.body, messages: updatedMessages } };
return [{ json: { ...config, voice_script, script_request } }];

const base = $input.first().json;
const plan = base.scene_plan || {};
let scenes = Array.isArray(plan.scenes) ? plan.scenes : [];
const voiceScript = (base.voice_script || base.narration_script || '').trim();
const requestedN = base.scene_count;
const targetDuration = base.target_duration_sec;
const errors = [];
const warnings = [];

// Normalize style_bible: AI sometimes returns object instead of string
if (plan.style_bible && typeof plan.style_bible !== 'string') {
  plan.style_bible = Object.values(plan.style_bible).filter(Boolean).join('. ');
}
if (plan.character_bible && typeof plan.character_bible !== 'string') {
  plan.character_bible = Object.values(plan.character_bible).filter(Boolean).join('. ');
}

// Check 1: scene count
const actualN = scenes.length;
if (actualN === 0) {
  throw new Error('Manifest fatal: scenes array is empty — AI returned no scenes');
}
if (requestedN !== null && requestedN !== undefined && actualN !== requestedN) {
  const diff = Math.abs(actualN - requestedN);
  if (diff > 2) {
    throw new Error(`Manifest fatal: got ${actualN} scenes, expected ${requestedN} (diff ${diff} > 2 — beyond repair threshold)`);
  }
  errors.push(`scene_count mismatch: got ${actualN}, expected ${requestedN}`);
}

// Check 2: required fields per scene
for (const scene of scenes) {
  const id = scene.scene_id ?? '?';
  if (!scene.narration_text) {
    throw new Error(`Manifest fatal: scene ${id} missing narration_text — cannot recover without verbatim script`);
  }
  if (!scene.image_prompt) {
    errors.push(`scene ${id} missing image_prompt`);
  }
  for (const f of ['video_prompt', 'camera_motion', 'sound_design']) {
    if (scene[f] === undefined || scene[f] === null || scene[f] === '') {
      warnings.push(`scene ${id} missing optional ${f}`);
    }
  }
  if (scene.has_character === undefined || scene.has_character === null) {
    warnings.push(`scene ${id} missing has_character`);
  }
}

// Check 3: narration concat ≈ voice_script (fuzzy word similarity)
function norm(s) {
  return s.toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
}
function wordSim(a, b) {
  const wA = a.split(/\s+/).filter(Boolean);
  const wB = b.split(/\s+/).filter(Boolean);
  if (wA.length === 0 && wB.length === 0) return 1.0;
  const freq = {};
  wA.forEach(w => freq[w] = (freq[w] || 0) + 1);
  let common = 0;
  wB.forEach(w => { if (freq[w] > 0) { common++; freq[w]--; } });
  return common / Math.max(wA.length, wB.length);
}
const concatNarr = scenes.map(s => s.narration_text).join(' ');
const similarity = wordSim(norm(concatNarr), norm(voiceScript));
const simPct = Math.round(similarity * 100);

if (similarity < 0.70) {
  throw new Error(`Manifest fatal: narration similarity ${simPct}% < 70% — AI rewrote script instead of splitting verbatim`);
}
if (similarity < 0.95) {
  errors.push(`narration_similarity: ${simPct}% (below 95% threshold)`);
}

// Check 4: duration range (warn only — not fatal, scene seconds may vary)
if (targetDuration && scenes.length > 0) {
  const maxEnd = Math.max(...scenes.map(s => s.end_sec || 0));
  if (maxEnd > 0) {
    const ratio = maxEnd / targetDuration;
    if (ratio < 0.5 || ratio > 2.0) {
      warnings.push(`duration: last end_sec=${maxEnd}s vs target=${targetDuration}s (ratio ${ratio.toFixed(2)} outside 0.5–2.0)`);
    }
  }
}

const repair_needed = errors.length > 0;
return [{ json: {
  ...base,
  scene_plan: { ...plan, scenes },
  manifest_valid: !repair_needed,
  manifest_repair_needed: repair_needed,
  manifest_errors: errors,
  manifest_warnings: warnings,
  manifest_narration_similarity: simPct,
} }];

const base = $input.first().json;
const prov = base.providers.script;
const plan = base.scene_plan;
const errors = base.manifest_errors || [];
const voiceScript = base.voice_script || base.narration_script || '';
const sceneCount = base.scene_count;
const sceneSeconds = base.scene_seconds || 8;

const systemPrompt = `You are a JSON repair specialist for video scene plans. Fix ONLY the listed errors without changing anything that is already correct. Output STRICT JSON only — no markdown fences, no explanation.`;

const userMsg = `Repair the scene plan JSON below.

Voice-over script (scenes must split this verbatim):
"""
${voiceScript}
"""

Requested scene count: ${sceneCount || 'inferred from script length'}
Target ~${sceneSeconds}s per scene

Errors to fix:
${errors.map((e, i) => `${i + 1}. ${e}`).join('\n')}

Broken JSON:
${JSON.stringify(plan, null, 2)}

Rules:
- scenes array MUST have exactly ${sceneCount || 'the correct number of'} items
- Each narration_text must be a verbatim substring of the voice-over script above
- Concatenating all narration_text values must reconstruct the full voice-over script
- Preserve image_prompt, video_prompt, camera_motion, sound_design from original where correct

Output only the corrected JSON object with top-level keys: style_bible, character_bible, scenes[].`;

let repair_request;
if (prov.requestFormat === 'claude_messages') {
  repair_request = {
    url: prov.url,
    headers: {
      'x-api-key': prov.authValue,
      'anthropic-version': ((prov.extraHeaders || {})['anthropic-version'] || '2023-06-01'),
      'content-type': 'application/json',
    },
    body: { model: prov.model, max_tokens: 4096, system: systemPrompt, messages: [{ role: 'user', content: userMsg }] },
  };
} else {
  repair_request = {
    url: prov.url,
    headers: { [prov.authName]: prov.authValue, 'content-type': 'application/json' },
    body: { model: prov.model, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMsg }] },
  };
}
return [{ json: { ...base, repair_request } }];

const resp = $input.first().json;
const config = $('Code - Build Repair Request').first().json;

let rawText = '';
if (resp.content?.[0]?.text) {
  rawText = resp.content[0].text.trim();
} else if (resp.choices?.[0]?.message?.content) {
  rawText = resp.choices[0].message.content.trim();
}
if (!rawText) throw new Error('AI Repair: LLM returned empty response');

// Strip markdown fences
rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

let plan;
try {
  plan = JSON.parse(rawText);
} catch (e) {
  throw new Error(`AI Repair: JSON parse failed — ${e.message}. Response: ${rawText.slice(0, 200)}`);
}

const scenes = Array.isArray(plan.scenes) ? plan.scenes : [];
const requestedN = config.scene_count;
const voice = (config.voice_script || config.narration_script || '').trim();

// Fatal checks — repair already tried once
if (scenes.length === 0) throw new Error('AI Repair failed: repaired plan has no scenes');
if (requestedN && Math.abs(scenes.length - requestedN) > 2) {
  throw new Error(`AI Repair failed: still wrong scene count — got ${scenes.length}, expected ${requestedN}`);
}
for (const s of scenes) {
  if (!s.narration_text) throw new Error(`AI Repair failed: scene ${s.scene_id} still missing narration_text`);
}

function norm(s) { return s.toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim(); }
function wordSim(a, b) {
  const wA = a.split(/\s+/).filter(Boolean), wB = b.split(/\s+/).filter(Boolean);
  if (!wA.length && !wB.length) return 1;
  const freq = {};
  wA.forEach(w => freq[w] = (freq[w] || 0) + 1);
  let common = 0;
  wB.forEach(w => { if (freq[w] > 0) { common++; freq[w]--; } });
  return common / Math.max(wA.length, wB.length);
}
const sim = wordSim(norm(scenes.map(s => s.narration_text).join(' ')), norm(voice));
const simPct = Math.round(sim * 100);
if (sim < 0.70) throw new Error(`AI Repair failed: narration similarity still ${simPct}% after repair`);

// Normalize bibles to string
if (plan.style_bible && typeof plan.style_bible !== 'string') {
  plan.style_bible = Object.values(plan.style_bible).filter(Boolean).join('. ');
}
if (plan.character_bible && typeof plan.character_bible !== 'string') {
  plan.character_bible = Object.values(plan.character_bible).filter(Boolean).join('. ');
}

return [{ json: {
  ...config,
  scene_plan: plan,
  manifest_valid: true,
  manifest_repaired: true,
  manifest_repair_needed: false,
  manifest_narration_similarity: simPct,
} }];
